-- 包含表: backup_log, baltan_reference, categories, fee_rules, misc_sales, monster_favorites, pool_logs, products, sales, settings, shipments, shipping_rules, suppliers, supplies, supply_logs, toys, users, xplus_reference
-- 还原方法: sqlite3 data.db < 本文件
-- 或用 sql.js 读 .sql 解析执行

CREATE TABLE backup_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  filename TEXT,
  size INTEGER,
  created_at TEXT DEFAULT (datetime('now'))
);

-- 共 244 行

CREATE TABLE baltan_reference (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      ref_id TEXT NOT NULL,
      generation INTEGER NOT NULL,
      source TEXT NOT NULL,
      detail_url TEXT,
      position INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    , image_url TEXT, image_big_url TEXT, series TEXT, character_slug TEXT, character_name_ja TEXT, brand TEXT, is_custom INTEGER DEFAULT 0, character_name_zh TEXT);

-- 共 2800 行

CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, color TEXT DEFAULT '#6b7085', created_at TEXT DEFAULT (datetime('now')), parent_id INTEGER);

-- 共 61 行

CREATE TABLE fee_rules (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  fee_type TEXT,     -- xianyu/huabei/other
  rate REAL,
  flat_fee REAL DEFAULT 0,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (fee_rules 表为空)

CREATE TABLE misc_sales (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category TEXT DEFAULT '其他',
  sell_price REAL,
  sell_date TEXT,
  profit REAL,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (misc_sales 表为空)

CREATE TABLE monster_favorites (
      character_slug TEXT NOT NULL,
      ref_id TEXT NOT NULL DEFAULT '',
      note TEXT,
      created_at TEXT DEFAULT (datetime('now')), reference_price REAL, linked_toy_id INTEGER,
      PRIMARY KEY (character_slug, ref_id)
    );

-- 共 18 行

CREATE TABLE pool_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      product_id INTEGER,
      toy_id INTEGER,
      action TEXT NOT NULL,
      toy_name TEXT,
      quantity INTEGER,
      unit_cost REAL,
      total_cost REAL,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

-- 共 103 行

CREATE TABLE products (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      name_zh TEXT DEFAULT '',
      category TEXT DEFAULT '其他',
      source TEXT DEFAULT 'direct',
      image TEXT,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

-- 共 49 行

CREATE TABLE sales (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      product_id INTEGER,
      toy_id INTEGER,
      quantity INTEGER DEFAULT 1,
      sell_price REAL,
      total_revenue REAL DEFAULT 0,
      huabei REAL DEFAULT 0,
      software_service_fee REAL DEFAULT 0,
      basic_software_service_fee REAL DEFAULT 0,
      worry_free_service_fee REAL DEFAULT 0,
      refund_amount REAL DEFAULT 0,
      logistics_fee REAL DEFAULT 0,
      box_fee REAL DEFAULT 0,
      packing_fee REAL DEFAULT 0,
      logistics_region TEXT DEFAULT '',
      logistics_weight REAL DEFAULT 0,
      sell_date TEXT,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

-- 共 29 行

CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT,
  updated_at TEXT DEFAULT (datetime('now'))
);

-- 共 5 行

CREATE TABLE shipments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  status TEXT DEFAULT 'preparing',  -- preparing/in_transit/arrived
  total_weight REAL DEFAULT 0,
  total_intl_shipping REAL DEFAULT 0,
  arrived_date TEXT,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (shipments 表为空)

CREATE TABLE shipping_rules (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      carrier TEXT DEFAULT 'zto',
      provinces TEXT,
      first_weight REAL DEFAULT 1,
      first_fee REAL DEFAULT 0,
      additional_weight REAL DEFAULT 1,
      additional_fee REAL DEFAULT 0,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

-- 共 31 行

CREATE TABLE suppliers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  source TEXT,
  contact TEXT,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (suppliers 表为空)

CREATE TABLE supplies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category TEXT DEFAULT 'box',
  stock INTEGER DEFAULT 0,
  unit TEXT DEFAULT '个',
  unit_price REAL DEFAULT 0,
  low_stock_threshold INTEGER DEFAULT 5,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (supplies 表为空)

CREATE TABLE supply_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  supply_id INTEGER,
  amount INTEGER,
  reason TEXT,
  toy_id INTEGER,
  created_at TEXT DEFAULT (datetime('now'))
);

-- (supply_logs 表为空)

CREATE TABLE toys (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category TEXT DEFAULT '其他',
  source TEXT DEFAULT 'direct',   -- direct/proxy/domestic/secondhand
  status TEXT DEFAULT 'procurement', -- procurement/transit/stock/sold/done/returned

  -- 采购基础
  supplier_id INTEGER,
  purchase_date TEXT,
  supplier_name TEXT,

  -- 直购
  japan_price_jpy REAL DEFAULT 0,
  japan_price_cny REAL DEFAULT 0,
  handling_fee REAL DEFAULT 0,
  japan_domestic_shipping REAL DEFAULT 0,

  -- 代购
  proxy_price REAL DEFAULT 0,
  proxy_intl_shipping REAL DEFAULT 0,
  proxy_domestic_shipping REAL DEFAULT 0,

  -- 国内 / 二手
  domestic_price REAL DEFAULT 0,
  domestic_shipping REAL DEFAULT 0,

  -- 国际
  intl_shipping REAL DEFAULT 0,
  import_duty REAL DEFAULT 0,

  -- 仓储发货
  logistics_type TEXT DEFAULT '',
  logistics_fee REAL DEFAULT 0,
  logistics_tracking TEXT DEFAULT '',
  logistics_weight REAL DEFAULT 0,
  logistics_region TEXT DEFAULT '',
  box_size TEXT DEFAULT '',
  box_fee REAL DEFAULT 0,
  packing_fee REAL DEFAULT 0,

  -- 销售
  sell_price REAL,
  sell_date TEXT,
  huabei REAL DEFAULT 0,
  refund_amount REAL DEFAULT 0,

  -- 采购阶段（在途用）
  procurement_stage TEXT DEFAULT 'stage1', -- stage1/stage2/stage3/stocked
  stage1_date TEXT,
  stage1_amount REAL DEFAULT 0,
  stage1_note TEXT,
  stage1_jpy REAL DEFAULT 0,
  stage1_handling REAL DEFAULT 0,
  stage1_domestic_ship REAL DEFAULT 0,

  stage2_date TEXT,
  stage2_amount REAL DEFAULT 0,
  stage2_note TEXT,
  stage2_handling REAL DEFAULT 0,
  stage2_domestic_ship REAL DEFAULT 0,

  stage3_date TEXT,
  stage3_amount REAL DEFAULT 0,
  stage3_note TEXT,
  stage3_intl_ship REAL DEFAULT 0,
  stage3_tax REAL DEFAULT 0,

  -- 发货批次
  shipment_id INTEGER,

  -- 计算字段（由后端写入）
  total_cost REAL DEFAULT 0,
  profit REAL,

  -- 元数据
  image TEXT,
  notes TEXT,
  created_at TEXT DEFAULT (datetime('now'))
, japan_consumption_tax REAL DEFAULT 0, japan_price_includes_tax INTEGER DEFAULT 0, baltan_ref_id TEXT, expected_arrival_date TEXT, software_service_fee REAL DEFAULT 0, basic_software_service_fee REAL DEFAULT 0, worry_free_service_fee REAL DEFAULT 0, stage3_tax_mode TEXT DEFAULT 'normal', name_zh TEXT DEFAULT '', product_id INTEGER, quantity INTEGER, remaining INTEGER, unit_cost REAL);

-- 共 562 行

CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now'))
    );

-- 共 1 行

CREATE TABLE xplus_reference (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      ref_id TEXT NOT NULL,
      series TEXT NOT NULL,
      series_name_ja TEXT,
      product_name TEXT,
      release_date TEXT,
      material TEXT,
      specs TEXT,
      height TEXT,
      price TEXT,
      package_info TEXT,
      accessories TEXT,
      variations TEXT,
      detail_url TEXT,
      image_url TEXT,
      images TEXT,
      source_type TEXT,
      position INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    , character_name TEXT);

